const rows = $input.all().map((item) => item.json);

const toText = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toKey = (value) => toText(value).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');

const parseDate = (value) => {
  const text = toText(value);
  if (!text) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    const parsed = new Date(`${text}T00:00:00Z`);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }
  const parsed = new Date(text);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
};

const formatIso = (date) => {
  if (!date) return '';
  return date.toISOString().slice(0, 10);
};

const formatLong = (date) => {
  if (!date) return '';
  return new Intl.DateTimeFormat('en-US', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    timeZone: 'UTC'
  }).format(date);
};

const addDays = (date, days) => {
  const copy = new Date(date.getTime());
  copy.setUTCDate(copy.getUTCDate() + days);
  return copy;
};

const normalizeStatus = (value) => {
  const key = toKey(value);
  if (['done', 'complete', 'completed', 'finished'].includes(key)) return 'done';
  if (['doing', 'in_progress', 'inprogress', 'current', 'active', 'wip'].includes(key)) return 'doing';
  if (['next', 'up_next', 'upnext', 'planned', 'todo', 'pending'].includes(key)) return 'next';
  if (['blocked', 'blocker', 'on_hold', 'onhold'].includes(key)) return 'blocked';
  return 'next';
};

const meta = {};
const tasks = [];

for (const row of rows) {
  const rowType = toKey(row.row_type || row.type || '');
  const key = toKey(row.key || row.meta_key || '');
  const value = toText(row.value || row.meta_value || '');
  const title = toText(row.title || row.task || row.task_title || '');
  const statusText = toText(row.status || '');

  if (rowType === 'meta' || (!title && key && value)) {
    if (key) meta[key] = value;
    continue;
  }

  if (!title && !statusText) continue;

  const projectedDayValue = parseInt(toText(row.projected_day || row.day || row.plan_day || ''), 10);
  const sortOrderValue = parseInt(toText(row.sort_order || row.order || ''), 10);

  tasks.push({
    taskId: toText(row.task_id || row.id || ''),
    title,
    status: normalizeStatus(statusText),
    rawStatus: statusText,
    details: toText(row.details || row.description || row.notes || ''),
    workstream: toText(row.workstream || row.track || ''),
    projectedDay: Number.isInteger(projectedDayValue) ? projectedDayValue : null,
    dateSet: toText(row.date_set || row.plan_set_date || ''),
    dueDate: toText(row.due_date || ''),
    owner: toText(row.owner || row.assignee || ''),
    sortOrder: Number.isInteger(sortOrderValue) ? sortOrderValue : 9999
  });
}

const projectName = meta.project_name || 'Client Project';
const clientName = meta.client_name || 'Client';
const baseDate = parseDate(meta.five_day_start_date || meta.plan_set_date || meta.date_set || tasks.find((task) => task.dateSet)?.dateSet || '2026-08-13') || new Date('2026-08-13T00:00:00Z');
const reportDate = parseDate(meta.report_date) || baseDate;

const sortTasks = (list) => list.slice().sort((a, b) => {
  if (a.sortOrder !== b.sortOrder) return a.sortOrder - b.sortOrder;
  return a.title.localeCompare(b.title);
});

const done = sortTasks(tasks.filter((task) => task.status === 'done'));
const doing = sortTasks(tasks.filter((task) => task.status === 'doing'));
const next = sortTasks(tasks.filter((task) => task.status === 'next'));
const blocked = sortTasks(tasks.filter((task) => task.status === 'blocked'));

const projection = Array.from({ length: 5 }, (_, index) => {
  const dayNumber = index + 1;
  const date = addDays(baseDate, index);
  const items = sortTasks(tasks.filter((task) => task.projectedDay === dayNumber));
  return {
    day_number: dayNumber,
    date: formatIso(date),
    date_label: formatLong(date),
    items
  };
});

const taskLine = (task) => {
  const parts = [task.title];
  if (task.details) parts.push(task.details);
  if (task.workstream) parts.push(`workstream: ${task.workstream}`);
  if (task.owner) parts.push(`owner: ${task.owner}`);
  if (task.dueDate) parts.push(`due: ${task.dueDate}`);
  return `- ${parts.join(' | ')}`;
};

const renderSection = (title, list, emptyText) => {
  if (!list.length) {
    return `## ${title}\n\n- ${emptyText}`;
  }
  return `## ${title}\n\n${list.map(taskLine).join('\n')}`;
};

const projectionMarkdown = projection.map((day) => {
  const header = `### Day ${day.day_number} - ${day.date_label}`;
  const body = day.items.length ? day.items.map(taskLine).join('\n') : '- No projected items assigned yet.';
  return `${header}\n\n${body}`;
}).join('\n\n');

const progressChecklistMarkdown = [
  `# ${projectName} - Client Progress Update`,
  '',
  `Client: ${clientName}`,
  `Report date: ${formatLong(reportDate)}`,
  `Five-day plan set date: ${formatLong(baseDate)}`,
  '',
  renderSection('Done', done, 'No completed items recorded yet.'),
  '',
  renderSection('Doing Now', doing, 'No in-progress items recorded yet.'),
  '',
  renderSection('Next', next, 'No next items recorded yet.'),
  '',
  renderSection('Blocked', blocked, 'No blocked items recorded.'),
  '',
  '## Projected 5-Day Plan',
  '',
  projectionMarkdown
].join('\n');

const listPreview = (list, fallback) => {
  if (!list.length) return fallback;
  const titles = list.slice(0, 3).map((task) => task.title);
  if (list.length <= 3) return titles.join(', ');
  return `${titles.join(', ')}, and ${list.length - 3} more`;
};

const statusSentence = `${projectName} currently has ${done.length} completed item(s), ${doing.length} in progress, ${next.length} queued next${blocked.length ? `, and ${blocked.length} blocked` : ''}.`;
const accomplishmentSentence = done.length
  ? `Since ${formatLong(baseDate)}, the main completed work has been ${listPreview(done, 'the recorded completed tasks')}.`
  : `No completed items have been recorded yet since ${formatLong(baseDate)}.`;
const currentSentence = doing.length
  ? `Current work is focused on ${listPreview(doing, 'the active workstream list')}.`
  : 'There are no tasks currently marked as in progress.';
const nextSentence = next.length
  ? `Next up is ${listPreview(next, 'the next queued work')}.`
  : 'There are no tasks currently marked as next.';
const projectionSentence = `The five-day projection is anchored to ${formatLong(baseDate)} and gives the client a dated day-by-day view of what should happen next.`;
const blockerSentence = blocked.length
  ? `Blocked items to surface clearly for the client are ${listPreview(blocked, 'the blocked task list')}.`
  : 'There are currently no blocked items listed in the progress board.';

const clientExplanation = [
  statusSentence,
  accomplishmentSentence,
  currentSentence,
  nextSentence,
  projectionSentence,
  blockerSentence
].join(' ');

return [
  {
    json: {
      project_name: projectName,
      client_name: clientName,
      report_date: formatIso(reportDate),
      report_date_label: formatLong(reportDate),
      five_day_plan_set_date: formatIso(baseDate),
      five_day_plan_set_date_label: formatLong(baseDate),
      status_counts: {
        done: done.length,
        doing: doing.length,
        next: next.length,
        blocked: blocked.length
      },
      done_tasks: done,
      doing_tasks: doing,
      next_tasks: next,
      blocked_tasks: blocked,
      five_day_projection: projection,
      client_explanation: clientExplanation,
      progress_checklist_markdown: progressChecklistMarkdown
    }
  }
];
